1	package dashboard
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/charmbracelet/lipgloss"
8	
9		"github.com/anthnel/devdesk/internal/status"
10		"github.com/anthnel/devdesk/internal/ui/help"
11		"github.com/anthnel/devdesk/internal/ui/shortcut"
12		"github.com/anthnel/devdesk/internal/ui/theme"
13	)
14	
15	// sectionsToLines splits rendered sections into individual lines with background separators
16	func sectionsToLines(sections []string, colWidth int) []string {
17		emptyLine := theme.EmptyLineBg(colWidth)
18		var lines []string
19		for i, s := range sections {
20			lines = append(lines, strings.Split(s, "\n")...)
21			if i < len(sections)-1 {
22				lines = append(lines, emptyLine)
23			}
24		}
25		return lines
26	}
27	
28	// View renders the dashboard as a two-column layout
29	func (m Model) View() string {
30		colWidth := m.columnWidth()
31	
32		// Left column: GitLab, Services, Certificates, Workspaces
33		leftSections := []string{
34			m.renderGitLabSection(colWidth),
35			m.renderServicesSection(colWidth),
36			m.renderCertificatesSection(colWidth),
37			m.renderWorkspacesSection(colWidth),
38		}
39	
40		// Right column: OCI, Containers, Tools
41		rightSections := []string{
42			m.renderOCISection(colWidth),
43			m.renderContainersSection(colWidth),
44			m.renderToolsSection(colWidth),
45		}
46	
47		// Split sections into lines
48		leftLines := sectionsToLines(leftSections, colWidth)
49		rightLines := sectionsToLines(rightSections, colWidth)
50	
51		// Equalize heights
52		emptyLine := theme.EmptyLineBg(colWidth)
53		maxH := len(leftLines)
54		if len(rightLines) > maxH {
55			maxH = len(rightLines)
56		}
57		for len(leftLines) < maxH {
58			leftLines = append(leftLines, emptyLine)
59		}
60		for len(rightLines) < maxH {
61			rightLines = append(rightLines, emptyLine)
62		}
63	
64		// Combine columns line by line (no JoinHorizontal)
65		var rows []string
66		for i := 0; i < maxH; i++ {
67			rows = append(rows, theme.PadWithBg(leftLines[i], colWidth)+theme.PadWithBg(rightLines[i], colWidth))
68		}
69	
70		content := strings.Join(rows, "\n")
71		return lipgloss.Place(m.width, m.height, lipgloss.Center, lipgloss.Top,
72			lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1).Render(content),
73			lipgloss.WithWhitespaceBackground(theme.ColorBackground))
74	}
75	
76	// renderGitLabSection renders the GitLab card (without Projects/Groups)
77	func (m Model) renderGitLabSection(width int) string {
78		var b strings.Builder
79	
80		b.WriteString(theme.SubTitleStyle.Render(theme.IconGitlab+" GitLab") + "\n\n")
81	
82		if !m.shared.IsAuthenticated {
83			b.WriteString(theme.DimStyle.Render("Not connected"))
84			b.WriteString("\n")
85			b.WriteString(theme.HelpStyle.Render("Authenticate with :gitlab-auth"))
86			return m.renderSection(b.String(), width)
87		}
88	
89		if m.loadingGitLab {
90			b.WriteString(theme.DimStyle.Render("Loading..."))
91			return m.renderSection(b.String(), width)
92		}
93	
94		if m.shared.CurrentUser != nil {
95			b.WriteString(theme.StatusOKStyle.Render("✓ Connected") + theme.Bg(" as ") + theme.PrimaryColorStyle.Bold(true).Render(m.shared.CurrentUser.Username))
96			b.WriteString("\n\n")
97		}
98	
99		if m.gitlabStats != nil {
100			stats := m.gitlabStats
101			b.WriteString(theme.Bg("Merge Requests:  ") + renderCount(stats.AssignedMRs) + theme.Bg(" assigned, ") + renderCount(stats.ReviewMRs) + theme.Bg(" to review"))
102			b.WriteString("\n")
103			b.WriteString(theme.Bg("Issues:          ") + renderCount(stats.AssignedIssues) + theme.Bg(" assigned"))
104		}
105	
106		b.WriteString("\n")
107	
108		return m.renderSection(b.String(), width)
109	}
110	
111	// renderServicesSection renders the services status card (non-SSL only)
112	func (m Model) renderServicesSection(width int) string {
113		var b strings.Builder
114	
115		b.WriteString(theme.SubTitleStyle.Render(theme.IconService+" Services") + "\n\n")
116	
117		if m.loadingServices {
118			b.WriteString(theme.DimStyle.Render("Loading..."))
119			return m.renderSection(b.String(), width)
120		}
121	
122		services := m.filterComponents(false)
123	
124		if len(services) == 0 {
125			b.WriteString(theme.DimStyle.Render("No monitors configured"))
126			b.WriteString("\n")
127			b.WriteString(theme.HelpStyle.Render("Configure in :status"))
128			return m.renderSection(b.String(), width)
129		}
130	
131		okCount, downCount, errorCount := countStatuses(services)
132	
133		b.WriteString(theme.StatusOKStyle.Render(fmt.Sprintf("✓ %d OK", okCount)))
134		if downCount > 0 {
135			b.WriteString(theme.Bg("  ") + theme.StatusDownStyle.Render(fmt.Sprintf("✗ %d Down", downCount)))
136		}
137		if errorCount > 0 {
138			b.WriteString(theme.Bg("  ") + theme.StatusErrorStyle.Render(fmt.Sprintf("%s %d Error", theme.IconWarning, errorCount)))
139		}
140	
141		b.WriteString("\n")
142	
143		return m.renderSection(b.String(), width)
144	}
145	
146	// renderCertificatesSection renders SSL certificate status
147	func (m Model) renderCertificatesSection(width int) string {
148		var b strings.Builder
149	
150		b.WriteString(theme.SubTitleStyle.Render(theme.IconCertificate+" Certificates") + "\n\n")
151	
152		if m.loadingServices {
153			b.WriteString(theme.DimStyle.Render("Loading..."))
154			return m.renderSection(b.String(), width)
155		}
156	
157		certs := m.filterComponents(true)
158	
159		if len(certs) == 0 {
160			b.WriteString(theme.DimStyle.Render("No SSL monitors"))
161			return m.renderSection(b.String(), width)
162		}
163	
164		okCount, downCount, errorCount := countStatuses(certs)
165	
166		b.WriteString(theme.StatusOKStyle.Render(fmt.Sprintf("✓ %d valid", okCount)))
167		if downCount > 0 {
168			b.WriteString(theme.Bg("  ") + theme.StatusDownStyle.Render(fmt.Sprintf("✗ %d expired", downCount)))
169		}
170		if errorCount > 0 {
171			b.WriteString(theme.Bg("  ") + theme.StatusErrorStyle.Render(fmt.Sprintf("%s %d warning", theme.IconWarning, errorCount)))
172		}
173	
174		b.WriteString("\n")
175	
176		return m.renderSection(b.String(), width)
177	}
178	
179	// renderWorkspacesSection renders the workspaces card with disk usage
180	func (m Model) renderWorkspacesSection(width int) string {
181		var b strings.Builder
182	
183		b.WriteString(theme.SubTitleStyle.Render(theme.IconWorkspace+" Workspaces") + "\n\n")
184	
185		if m.loadingWorkspaces {
186			b.WriteString(theme.DimStyle.Render("Loading..."))
187			return m.renderSection(b.String(), width)
188		}
189	
190		b.WriteString(theme.Bg(fmt.Sprintf("%d workspaces", m.workspaceCount)))
191		if m.workspaceDisk != "" {
192			b.WriteString(theme.DimStyle.Render(fmt.Sprintf("  (%s)", m.workspaceDisk)))
193		}
194		b.WriteString("\n")
195		b.WriteString(theme.DimStyle.Render(m.config.App.WorkspacesDir))
196	
197		return m.renderSection(b.String(), width)
198	}
199	
200	// renderOCISection renders OCI resource counts and disk usage
201	func (m Model) renderOCISection(width int) string {
202		var b strings.Builder
203	
204		b.WriteString(theme.SubTitleStyle.Render(theme.IconDocker+" OCI Resources") + "\n\n")
205	
206		if m.loadingOCI {
207			b.WriteString(theme.DimStyle.Render("Loading..."))
208			return m.renderSection(b.String(), width)
209		}
210	
211		if m.ociStats == nil || !m.ociStats.Available {
212			b.WriteString(theme.DimStyle.Render("Docker not available"))
213			return m.renderSection(b.String(), width)
214		}
215	
216		s := m.ociStats
217		b.WriteString(theme.Bg("Images:      ") + renderCountWithSize(s.ImagesCount, s.ImagesSize))
218		b.WriteString("\n")
219		b.WriteString(theme.Bg("Containers:  ") + renderCountWithSize(s.ContainersCount, s.ContainersSize))
220		b.WriteString("\n")
221		b.WriteString(theme.Bg("Volumes:     ") + renderCountWithSize(s.VolumesCount, s.VolumesSize))
222	
223		b.WriteString("\n")
224	
225		return m.renderSection(b.String(), width)
226	}
227	
228	// renderContainersSection renders container counts by state
229	func (m Model) renderContainersSection(width int) string {
230		var b strings.Builder
231	
232		b.WriteString(theme.SubTitleStyle.Render(theme.IconContainer+" Containers") + "\n\n")
233	
234		if m.loadingDocker {
235			b.WriteString(theme.DimStyle.Render("Loading..."))
236			return m.renderSection(b.String(), width)
237		}
238	
239		if m.dockerStats == nil || !m.dockerStats.Available {
240			b.WriteString(theme.DimStyle.Render("Docker not available"))
241			return m.renderSection(b.String(), width)
242		}
243	
244		d := m.dockerStats
245		total := d.Running + d.Stopped + d.Paused
246	
247		b.WriteString(theme.Bg(fmt.Sprintf("%d containers", total)))
248		b.WriteString("\n")
249		b.WriteString(theme.StatusOKStyle.Render(fmt.Sprintf("%s %d running", theme.IconPlay, d.Running)))
250		if d.Stopped > 0 {
251			b.WriteString(theme.Bg("  ") + theme.DimStyle.Render(fmt.Sprintf("%s %d stopped", theme.IconStop, d.Stopped)))
252		}
253		if d.Paused > 0 {
254			b.WriteString(theme.Bg("  ") + theme.StatusWarningStyle.Render(fmt.Sprintf("%s %d paused", theme.IconPause, d.Paused)))
255		}
256	
257		b.WriteString("\n")
258	
259		return m.renderSection(b.String(), width)
260	}
261	
262	// renderToolsSection renders detected DevSecOps tools
263	func (m Model) renderToolsSection(width int) string {
264		var b strings.Builder
265	
266		b.WriteString(theme.SubTitleStyle.Render(theme.IconTools+" Tools") + "\n\n")
267	
268		if m.loadingTools {
269			b.WriteString(theme.DimStyle.Render("Detecting..."))
270			return m.renderSection(b.String(), width)
271		}
272	
273		if len(m.tools) == 0 {
274			b.WriteString(theme.DimStyle.Render("No tools detected"))
275			return m.renderSection(b.String(), width)
276		}
277	
278		// Find max tool name length for alignment
279		maxNameLen := 0
280		for _, tool := range m.tools {
281			if len(tool.Name) > maxNameLen {
