	n, err := net.IOCounters(false)
	fmt.Printf("net.IOCounters-> %v err=%v (%s)\n", n, err, time.Since(t0).Round(time.Millisecond))

	for _, p := range []string{"C:\\", "C:\\Users\\anthoni\\workspaces"} {
		t0 = time.Now()
		d, err := disk.Usage(p)
		if err == nil {
			fmt.Printf("disk %-32s -> %.1f%% used, free %.1f GB (%s)\n",
				p, d.UsedPercent, float64(d.Free)/1e9, time.Since(t0).Round(time.Millisecond))
		} else {
			fmt.Printf("disk %-32s -> err=%v\n", p, err)
		}
	}

	t0 = time.Now()
	l, err := load.Avg()
	fmt.Printf("load.Avg     -> %v err=%v (%s)\n", l, err, time.Since(t0).Round(time.Millisecond))

	t0 = time.Now()
	h, err := host.Info()
	if err == nil {
		fmt.Printf("host         -> %s %s, uptime %ds (%s)\n", h.Platform, h.PlatformVersion, h.Uptime, time.Since(t0).Round(time.Millisecond))
	} else {
		fmt.Printf("host         -> err=%v\n", err)
	}

	cores, _ := cpu.Counts(true)
	fmt.Printf("cpu.Counts   -> %d logical\n", cores)
}

